const input = $json.body ?? $json;
let request = input;
if (typeof request === 'string') { try { request = JSON.parse(request); } catch { request = {}; } }
const tags = request?.tags && typeof request.tags === 'object' ? request.tags : {};
const required = ['ai_project_id','ai_solution','ai_component','environment','business_unit','owner_team','cost_center','data_classification','risk_tier','criticality','lifecycle','chargeback_model'];
const allowed = { ai_component: ['supervisor_agent','genie_agent','knowledge_assistant','model_serving','vector_search','rag','tool','evaluator'], environment: ['dev','qa','staging','prod'], data_classification: ['public','internal','confidential','restricted'], risk_tier: ['low','medium','high','critical'], criticality: ['low','medium','high','mission_critical'], lifecycle: ['design','pilot','production','retired'], chargeback_model: ['direct','shared','allocated'] };
const issues = [];
const missing = required.filter((key) => tags[key] === undefined || tags[key] === null || String(tags[key]).trim() === '');
if (missing.length) issues.push(`Tags obrigatórias ausentes/vazias: ${missing.join(', ')}`);
for (const [key, values] of Object.entries(allowed)) if (tags[key] && !values.includes(String(tags[key]))) issues.push(`${key} inválida; valores permitidos: ${values.join(', ')}`);
if (tags.ai_solution && !/^[a-z0-9]+(?:[-_][a-z0-9]+)*$/.test(String(tags.ai_solution))) issues.push('ai_solution deve ser um slug minúsculo.');
if (tags.business_unit && !/^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(String(tags.business_unit))) issues.push('business_unit deve ser um slug/código sem espaços.');
if (tags.owner_team && String(tags.owner_team).includes('@')) issues.push('owner_team deve ser grupo institucional, não e-mail pessoal.');
if (tags.environment && tags.environment !== 'prod') issues.push('Este endpoint autoriza somente environment=prod.');
if (tags.lifecycle && tags.lifecycle !== 'production') issues.push('Promoção para produção exige lifecycle=production.');
if (tags.environment === 'prod' && tags.lifecycle && tags.lifecycle !== 'production') issues.push('environment=prod e lifecycle devem ser coerentes.');
const typeToComponent = { 'Supervisor Agent': 'supervisor_agent', 'Genie Agent': 'genie_agent', 'Knowledge Assistant': 'knowledge_assistant' };
if (request.agent_type && typeToComponent[request.agent_type] && tags.ai_component !== typeToComponent[request.agent_type]) issues.push(`ai_component deve ser ${typeToComponent[request.agent_type]} para o tipo informado.`);
const normalizedTags = Object.fromEntries(required.map((key) => [key, tags[key] === undefined || tags[key] === null ? '' : String(tags[key]).trim()]));
const invalid = issues.length > 0;
return [{ json: { valid: !invalid, issues: [...new Set(issues)], tags: normalizedTags, request_id: String(request.request_id || '').slice(0, 150), agent_name: String(request.agent_name || request.asset_name || '').slice(0, 300), agent_type: String(request.agent_type || 'AI Asset').slice(0, 100) } }];

const table = $env.GOVERNANCE_REGISTRY_TABLE || 'governance.ai_inventory.ai_solution_registry';
const warehouse = $env.DATABRICKS_SQL_WAREHOUSE_ID;
if (!warehouse) throw new Error('Defina DATABRICKS_SQL_WAREHOUSE_ID.');
if (!/^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*){2}$/.test(table)) throw new Error('GOVERNANCE_REGISTRY_TABLE deve ser catalog.schema.table.');
const required = ['ai_project_id','ai_solution','ai_component','environment','business_unit','owner_team','cost_center','data_classification','risk_tier','criticality','lifecycle','chargeback_model'];
const q = (v) => `'${String(v).replace(/'/g, "''")}'`;
const predicates = required.map((key) => `${key} = ${q($json.tags[key])}`);
const statement = `SELECT COUNT(1) AS approved_match FROM ${table} WHERE approved = TRUE AND ${predicates.join(' AND ')}`;
return [{ json: { ...$json, request: { warehouse_id: warehouse, statement, wait_timeout: '30s', on_wait_timeout: 'CONTINUE', disposition: 'INLINE', format: 'JSON_ARRAY' } } }];

const body = $json;
if (body.status?.state && body.status.state !== 'SUCCEEDED') throw new Error(`Consulta do AI Registry não concluiu: ${body.status.state} ${body.status.error?.message || ''}`);
const count = Number(body.result?.data_array?.[0]?.[0] || 0);
const approved = Number.isFinite(count) && count > 0;
const source = $('Consultar declaração aprovada no AI Registry').item.json;
return [{ json: { httpStatus: approved ? 200 : 403, response: { allow: approved, status: approved ? 'APPROVED' : 'BLOCKED_NOT_IN_AI_REGISTRY', request_id: source.request_id || null, asset: source.agent_name || null, message: approved ? 'Promoção autorizada: 12 tags válidas e correspondência exata aprovada no AI Registry.' : 'Promoção bloqueada: o conjunto de 12 tags não corresponde a uma declaração aprovada no AI Registry.', issues: approved ? [] : ['Declaração exata não encontrada ou não aprovada no AI Registry.'] } } }];
